def locate(t,pattern):
 m=re.search(pattern,t,re.I)
 if not m:return 'Not used',-1,''
 pos=m.start();section=list(re.finditer(r'(?m)^#{1,3} (.+)$',t[:pos+1]));name=section[-1].group(1) if section else 'Opening';line=t[:pos].count('\n')+1;para=next(p for p in t.split('\n\n') if m.group(0).lower() in p.lower())
 return f'{name}; line {line}',pos,para
audit=[];first=[];gloss=['# Abbreviations and nomenclature','', 'These definitions apply to the article and the unchanged supplementary evidence. Numerical stress and geometric proxies are not experimental stress or authenticated weld-toe measurements.','']
